DEFAULTS: dict[str, str] = {"mode": "fast", "level": "3"}


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys/values on DEFAULTS and return the resulting values.

    keys[i] is set to values[i]. The result lists the value of "mode",
    then the value of "level", then the values of any other keys in the
    order they first appear in keys. A repeated key takes its last value.
    """
    merged: dict[str, str] = dict(DEFAULTS)
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    head = [merged["mode"], merged["level"]]
    tail = [v for k, v in merged.items() if k not in DEFAULTS]
    return head + tail


def test_settings_defaults_only() -> None:
    assert settings([], []) == ["fast", "3"]


def test_settings_override_mode_and_level() -> None:
    assert settings(["level", "mode"], ["5", "slow"]) == ["slow", "5"]


def test_settings_extra_keys_in_given_order() -> None:
    assert settings(["color", "size"], ["red", "L"]) == ["fast", "3", "red", "L"]


def test_settings_mixed_defaults_and_extras() -> None:
    assert settings(["color", "mode"], ["red", "x"]) == ["x", "3", "red"]


def test_settings_repeated_key_takes_last_value() -> None:
    assert settings(["color", "color"], ["a", "b"]) == ["fast", "3", "b"]
